import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BDKIrnCI.js";const u=JSON.parse('{"title":"Agent tooling","description":"","frontmatter":{},"headers":[],"relativePath":"guides/agent-tooling.md","filePath":"docs/agent-tooling.md"}'),n={name:"guides/agent-tooling.md"};function i(d,e,r,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="agent-tooling" tabindex="-1">Agent tooling <a class="header-anchor" href="#agent-tooling" aria-label="Permalink to &quot;Agent tooling&quot;">​</a></h1><p>The repo keeps agent instructions, skills and executable checks separate:</p><ul><li><a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/AGENTS.md" target="_blank" rel="noreferrer">AGENTS.md</a> holds the shared rules and routes tasks to relevant docs and skills.</li><li><code>.agents/skills/</code> holds focused workflows. An agent can discover them or read the linked <code>SKILL.md</code> directly. They don&#39;t install hooks or grant permission for external actions.</li><li><code>.agents/hooks/</code> holds client-neutral Node scripts. Nothing in this folder runs automatically just because it is called a hook. A client must invoke it, or the agent must run it as instructed.</li></ul><p>There is no client-specific hook configuration in this repo. The portable runner inspects git status, so shell writes, deletions and renames are included alongside edits made through dedicated tools.</p><h2 id="run-checks-directly" tabindex="-1">Run checks directly <a class="header-anchor" href="#run-checks-directly" aria-label="Permalink to &quot;Run checks directly&quot;">​</a></h2><p>From the repo root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .agents/hooks/check.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .agents/hooks/check.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .agents/hooks/check.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/upnpumpkin/src/plugin.ts</span></span></code></pre></div><p><code>--plan</code> prints JSON with the files and commands without executing them. With no paths, the runner checks all staged, unstaged and untracked files. Explicit paths scope the run to your work and may include deleted files. Checks never apply lint fixes. Use scoped <code>pnpm exec biome check --write</code> and <code>pnpm exec eslint --fix</code> only on files you own when fixes are needed.</p><table tabindex="0"><thead><tr><th>Change</th><th>Checks</th></tr></thead><tbody><tr><td>Existing files</td><td>Biome; TypeScript files also get the JSDoc lint</td></tr><tr><td>Lint configuration</td><td>Whole-repo lint, to catch newly invalid existing code</td></tr><tr><td>Package code</td><td>Typecheck and unit tests for that package and workspace dependents</td></tr><tr><td>Shared root build inputs or lockfile</td><td>Typecheck and unit tests for all packages</td></tr><tr><td>Deleted package</td><td>All package typechecks and unit tests, to catch remaining imports</td></tr><tr><td>Scripts or hook code</td><td><code>pnpm test:scripts</code></td></tr><tr><td>Any relevant file</td><td><code>pnpm check</code> and <code>pnpm readme:check</code></td></tr><tr><td>Only generated output</td><td>No checks</td></tr></tbody></table><p>Markdown-only package edits skip package tests. <code>tools/build/src/</code> is source, not generated output. Real-server tests are deliberately separate; see <a href="./testing">Testing</a> and <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/.agents/skills/pumpkin-testing/SKILL.md" target="_blank" rel="noreferrer">the testing skill</a>.</p><p>The default run may report failures in somebody else&#39;s dirty files. Preserve their work and either report the failure or use explicit paths for your own validation. Passing these fast checks does not prove runtime behavior, correct prose or the full CI workflow.</p><h2 id="portable-hook-protocol" tabindex="-1">Portable hook protocol <a class="header-anchor" href="#portable-hook-protocol" aria-label="Permalink to &quot;Portable hook protocol&quot;">​</a></h2><p>A client adapter can run <code>node .agents/hooks/run.mjs</code> with one JSON request on stdin. The script writes one JSON response on stdout and exits <code>0</code> for success or <code>1</code> for refusal, check failure or invalid input. Resolve the script from the repository root; it runs checks there regardless of the caller&#39;s directory. A request&#39;s <code>cwd</code> only resolves its relative file paths and defaults to the repo root.</p><table tabindex="0"><thead><tr><th>Event</th><th>Request fields</th><th>Response</th></tr></thead><tbody><tr><td><code>before-tool</code></td><td><code>tool</code>, <code>input</code>, optional <code>cwd</code></td><td><code>ok</code>, replacement <code>input</code> when allowed, or <code>reason</code> when refused</td></tr><tr><td><code>plan</code></td><td>Optional <code>files</code> array and <code>cwd</code></td><td><code>ok</code>, <code>files</code>, <code>steps</code>; executes no checks</td></tr><tr><td><code>check</code></td><td>Optional <code>files</code> array and <code>cwd</code></td><td><code>ok</code>, <code>files</code>, <code>failures</code>, readable <code>report</code></td></tr></tbody></table><p>For example, stdin can contain:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.agents/hooks/run.mjs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>Shell tools accept <code>shell</code>, <code>bash</code> or <code>exec_command</code> and <code>input.command</code> or <code>input.cmd</code>. Edit tools accept <code>edit</code> or <code>write</code>, <code>path</code> or <code>filePath</code>, and <code>oldString</code> or full <code>content</code> respectively. Patch tools accept <code>patch</code> or <code>apply_patch</code>, with a string input or <code>patchText</code>, <code>patch</code> or <code>command</code> containing an apply-patch formatted patch. Unknown tool names pass through; unsupported event names fail. An adapter must translate its own tool names and payloads into this contract.</p><p>The optional before-tool guard catches common use of other package managers and direct edits to lockfiles, release-owned files, build output and generated README blocks. Shell matching is a heuristic, not a shell parser or security boundary. Shell-based file writes bypass edit guards. Patch edits to a README containing generated blocks are conservatively refused because the guard doesn&#39;t reconstruct patch hunks; use a precise edit outside the blocks, or regenerate from source. Plain Turbo runs receive <code>--output-logs=errors-only</code> unless they specify a log level or shell syntax. Git authorization remains in AGENTS.md; the guard cannot infer what the user authorized.</p><h2 id="integrating-an-agent-client" tabindex="-1">Integrating an agent client <a class="header-anchor" href="#integrating-an-agent-client" aria-label="Permalink to &quot;Integrating an agent client&quot;">​</a></h2><p>Translate the client&#39;s before-tool callback into <code>before-tool</code>, refuse an operation when <code>ok</code> is false, and use the returned input if the client supports rewriting. At completion, invoke <code>check</code>. Feed a failure report back only when the client supports continuation, and cap automatic retries to avoid loops. A hook failure must be visible; don&#39;t interpret malformed JSON, process errors or timeouts as a successful check. A blocking check report should tell the agent to preserve unrelated work.</p><p>Client APIs, hook trust, discovery locations and continuation schemas differ. Keep those details in an adapter owned by that client rather than baking them into shared repo checks. For example, consult the <a href="https://learn.chatgpt.com/docs/hooks" target="_blank" rel="noreferrer">Codex hook documentation</a> or <a href="https://opencode.ai/v2/docs/build/plugins" target="_blank" rel="noreferrer">OpenCode plugin documentation</a> before writing an adapter. Neither is installed by this repo.</p><h2 id="verify-the-tooling" tabindex="-1">Verify the tooling <a class="header-anchor" href="#verify-the-tooling" aria-label="Permalink to &quot;Verify the tooling&quot;">​</a></h2><p>Run <code>pnpm test:scripts</code> to exercise scope selection, status parsing, guards and the JSON protocol. Use <code>--plan</code> to confirm the expected packages are selected before a large run. For client integration, test an allowed call, a refused call, a failing completion check, the retry limit and a clean completion in a disposable checkout. Unit tests of the shared protocol don&#39;t prove a client loads an adapter.</p><p><code>pnpm check</code> also checks links, commands and repo paths in AGENTS.md and the skill documents, so these instructions don&#39;t silently drift away from the code they describe.</p>`,24)])])}const k=t(n,[["render",i]]);export{u as __pageData,k as default};
